```javascript
// ============================================================================
// CartClass — Gerenciador Avançado de Carrinhos de Compras (Discord + Pagamentos)
// Bot: Nyox Applications
// ============================================================================
//
// Requisições técnicas:
//   - Node.js ≥ 18 | discord.js ≥ 14.x | Mongoose ≥ 7 (driver monogood)
//   - Arquivo .env sugerido:
//     LOG_CHANNEL_ID=1264758034979360860
//     CARGO_CLIENT_ID=995154994183548953
//     INACTIVITY_DELAY_SEC=300          // segundos (padrão: 5 min)
//     POLL_INTERVAL_MS=30000            // checagem do status (padrão: 30s)
//     POLL_MAX_TRIES=20                 // máx. checagens antes de "falha na verificação"
//     (Observação: ajuste esses parâmetros às necessidades do seu fluxo)
//
// Estrutura esperada do ProductData:
//   {
//     productName: "NomeDoSistema",
//     preco: {
//       mensal: { preco: 59.90, onoff: true },
//       quizena: { preco: 34.90, onoff: true },
//       semanal: { preco: 14.50, onoff: true }
//     }
//   }
//
// Estrutura esperada do PaymentProcessor (método GET):
//   .getPayment(token)  -> Promise< { id: string, attachment?: Buffer, pixCopyPasteCode?: string }>
//   .checkPaymentStatus(id) -> Promise<string|Promise<string>>
//   .cancelPayment(paymentId) -> Promise<void>
//
// ============================================================================

const { EmbedBuilder, ActionRowBuilder, ButtonBuilder, ButtonStyle, ChannelType, ComponentType } = require('discord.js');
const PaymentProcessor = require('../structures/PaymentProcessor');
const crypto = require('crypto');

// ------------------------------------------------------------------
// Configurações globais (idealmente migrar para um arquivo .env)
// ------------------------------------------------------------------
const CFG = {
  LOG_CHANNEL_ID:           process.env.LOG_CHANNEL_ID           || '1264758034979360860',
  CARGO_CLIENT_ID:          process.env.CARGO_CLIENT_ID          || '995154994183548953',
  INACTIVITY_DELAY_SEC:     parseInt(process.env.INACTIVITY_DELAY_SEC || '300', 10),      // 5 min
  POLL_INTERVAL_MS:         parseInt(process.env.POLL_INTERVAL_MS || '30000', 10),        // 30s
  POLL_MAX_TRIES:           parseInt(process.env.POLL_MAX_TRIES || '20', 10),             // máx checagens
  COLLECTOR_TIMEOUT_MS:     600000,                                                        // 10 min sem clique ⇒ encerra
};

const STATUS_CART = { AGUARDANDO: 'Aguardando...', PROCESSANDO: 'Processando', PAGO: 'Pago', CANCELADO: 'Cancelado' };
const PLANO_DIAS  = { mensal: 30, quizena: 15, semanal: 7 };

// ------------------------------------------------------------------
// Utilitários
// ------------------------------------------------------------------

/**
 * Formata valor monetário no padrão brasileiro.
 * Ex.: 19.99 -> "R$ 19,99" | 1234.56 -> "R$ 1.234,56"
 */
function formatBRL(valor) {
  const n = Number(valor);
  if (!Number.isFinite(n) || isNaN(n) || n < 0) return 'R$ 0,00';

  const inteiro = Math.floor(n);
  const fracao  = (n - inteiro).toFixed(2).replace(/^0+/, '');
  const pad     = String(inteiro).padStart(2, '0').replace(/(\d{2})(\d)/g, '$1.$2');

  return `R$ ${pad}${fracao ? `,${fracao}` : ''}`;
}

function sleep(ms) { return new Promise(res => setTimeout(res, ms)); }

// ------------------------------------------------------------------
// Classe principal
// ------------------------------------------------------------------
class CartClass {

  /**
   * @param {Discord.Client} client
   * @param {Discord.Interaction|null} interaction - interação inicial do comando
   * @param {string} productId - identificador do produto (SKU/código interno)
   * @param {Object} productData - { productName, preco: { mensal/{preco,onoff}, quizena/{preco,onoff}, semanal/{preco,onoff} } }
   * @param {string|[Discord.GuildMember]} userId - fallback opcional do usuário (caso não haja interaction)
   */
  constructor(client, interaction, productId, productData, userId = null) {
    if (!productId) throw new Error('❌ productId é obrigatório.');
    if (!productData || typeof productData !== 'object') throw new Error('❌ productData é obrigatório.');
    if (!interaction && !userId) throw new Error('❌ interação ou userId são obrigatórios.');

    this.client               = client;
    this.interaction          = interaction;        // interação inicial do comando
    this.threadInteraction    = null;               // interação capturada dentro da thread (cliques)
    this.targetProductId      = productId;
    this.productData          = productData;

    // ---------- Resolução do usuário ----------
    let userObj;
    if (interaction?.user) userObj = interaction.user;
    else if (userId && client.users?.cache?.has(userId)) userObj = client.users.cache.get(userId);
    if (!userObj) throw new Error('❌ Usuário não foi identificado.');

    this.user       = userObj;
    this.user_id    = this.user.id;
    this.member     = null;                          // membro da guild (para aplicar cargos)
    this.cartId     = crypto.randomBytes(16).toString('hex');
    this.channel    = null;
    this.messageId  = null;
    this.quantity   = 1;
    this.selectedPlan = null;
    this.days       = null;
    this.processor  = new PaymentProcessor();        // instância única por instância de classe
    this._deleted   = false;
    this.inactivityTimer = null;
    this.inactivityDelay = CFG.INACTIVITY_DELAY_SEC * 1000;
  }

  // ==================================================================
  // MÉTODOS AUXILIARES
  // ==================================================================

  /**
   * Tenta resolver o canal do carrinho a partir do objeto guardado nesta classe.
   */
  _resolverCanal() {
    if (this.channel) {
      try {
        const c = this.client.channels.cache.get(this.channel.id);
        return c ?? null;
      } catch (_) { /* cache perdido */ }
    }
    if (this.interaction?.guild?.channels?.cache?.has?.(this.channel?.id)) {
      return this.interaction.guild.channels.cache.get(this.channel.id);
    }
    return null;
  }

  /** Tenta carregar um canal antigo conhecido pelo seu id. */
  _carregarCanal(id) {
    try {
      this.channel = this.client.channels.cache.get(id)
                    ?? this.interaction?.guild?.channels?.cache?.get(id);
      if (!this.channel) throw new Error('Canal do carrinho não localizado.');
    } catch (_) {
      this.channel = null;
    }
  }

  /** Confirma rapidamente que o canal ainda existe e é acessível. */
  _canalAtivo() {
    const ch = this.channel;
    try { ch.messages.count().catch(() => {}); return true; } catch { return false; }
    return !!ch;
  }

  /**
   * Busca o membro da guild do usuário (com fallbacks por diferentes interações).
   */
  _resolverMembro() {
    return this.member
      ?? (this.threadInteraction
          ? this.threadInteraction.guild.members.cache.get(this.user.id)
          : null);
  }

  /**
   * Envia mensagem/embbed para o usuário (DM) e, como fallback, para o canal.
   */
  async _avisoUsuario(ch, embeds) {
    try {
      await this.user.send({ embeds }).catch(() => {});
    } catch (_) { /* DM negada/bot não seguido — ignora */ }

    if (ch) {
      await ch.send({ embeds }).catch(() => {});
    }
  }

  /** Capitaliza cada palavra de forma segura. */
  _capitalize(str) {
    if (!str) return '';
    return str.split(' ').map(w => {
      if (w.length === 1) return w.toUpperCase();
      return w.charAt(0).toUpperCase() + w.slice(1).toLowerCase();
    }).join(' ');
  }

  /** Garante que o plano selecionado existe nas configs de preço. */
  _garantirPlano(selecionado) {
    const p = this.productData?.preco;
    if (!p) throw new Error('❌ Preços do produto não estão configurados.');
    if (!p[selecionado]) throw new Error(`❌ Plano "${selecionado}" não está disponível.`);
  }

  /** Wrapper de callback com chamada correta de `this` (evita vazamento de memória). */
  static _envolverCallback(cb) {
    if (!cb) return () => {};
    return (...args) => cb.call(this, ...args);
  }

  /**
   * Agenda o timer de inatividade (remove timers antigos para evitar duplicidade).
   * @param {Function} callback
   */
  _agendarInatividade(callback) {
    this._limparTimer();
    this.inactivityTimer = setTimeout(CartClass._envolverCallback(() => callback()), this.inactivityDelay);
  }

  _limparTimer() {
    if (this.inactivityTimer) {
      clearInterval(this.inactivityTimer);
      this.inactivityTimer = null;
    }
  }

  /** Envio silencioso por canal (falhas são ignoradas). */
  static _envioSilencioso(channel, data) {
    if (!channel) return;
    try { return channel.send(data).catch(() => null); } catch (_) { return null; }
  }

  /** Manda logs para o canal configurado. */
  sendLog(embed, meta = {}) {
    const ch = this._resolvCanalLogs();
    if (!ch) return;
    const payload = { embeds: [embed] };
    if (meta.titulo) payload.fields = [{ name: '📌 Categoria', value: meta.titulo, inline: false }];
    return CartClass._envioSilencioso(ch, payload);
  }

  _resolvCanalLogs() {
    try {
      const c = this.client.channels.cache.get(CFG.LOG_CHANNEL_ID);
      return c ?? null;
    } catch (_) { return null; }
  }

  consoleInfo(msg, ...rest) { console.info('[CART]', msg, ...rest); }
  consoleWarn(msg, ...rest) { console.warn('[CART]', msg, ...rest); }
  consoleError(msg, ...rest){ console.error('[CART]', msg, ...rest); }

  // ==================================================================
  // 1) CRIAÇÃO / REUTILIZAÇÃO DO CARRINHO
  // ==================================================================

  /**
   * Cria o carrinho (thread + registro) OU reaproveita um carrinho existente.
   */
  async criarCarrinho() {
    try {
      // ── Reaproveitamento de carrinho existente ──
      const existente = await Cart.findOne({ userId: this.user.id, status: { $eq: STATUS_CART.AGUARDANDO } });
      if (existente) {
        this._restaurarExistente(existente);
        this._carregarCanal(existente.channelId);

        if (this.channel && this._canalAtivo()) {
          await this._exibirUI();
          this._agendarInatividade(() => this.handleInatividade(), CFG.INACTIVITY_DELAY_SEC);
          return;
        }

        // Canal antigo indisponível (removido pelo Discord, etc.)
        this.consoleWarn('Canal do carrinho antigo não recuperável — não será criado um novo (evitaria duplicidade).');
        if (this.interaction) {
          await this.interaction.reply({
            content: '⚠️ O carrinho anterior não pôde ser recuperado. Por favor, tente iniciar novamente em instantes.',
            ephemeral: true,
          }).catch(() => {});
        }
        this.inactivityTimer = null; // nada mais a fazer
        return;
      }

      // ── Verifica se há outro carrinho do usuário em andamento (status diferente de Aguardando) ──
      const outroCartao = await Cart.findOne({ userId: this.user.id });
      if (outroCartao && outroCartao.status !== STATUS_CART.AGUARDANDO) {
        this.consoleWarn(`Carrinho já ativo com status "${outroCartao.status}" — não reutilizando.`);
        const msgTipo = outroCartao.status === STATUS_CART.PAGO
          ? '✅ Sua compra já foi concluída!'
          : `⚠️ Já existe um carrinho ativo para você (status: "${outroCartao.status}").`;

        if (this.interaction) {
          await this.interaction.reply({ content: msgTipo, ephemeral: true }).catch(() => {});
        }
        this.inactivityTimer = null;
        return;
      }

      // ── Fluxo normal: criar thread privada + carrinho ──
      if (this.interaction) {
        await this.interaction.reply({ content: 'Montando seu carrinho… aguarde um instante.', ephemeral: true }).catch(() => {});
      }

      const thread = await this._threadPrivado();
      this.channel = thread;

      // Registro no banco
      await Cart.updateOne(
        { userId: this.user.id, productId: this.targetProductId },
        {
          userId:        this.user.id,
          quantity:      1,
          cartId:        this.cartId,
          productId:     this.targetProductId,
          status:        STATUS_CART.AGUARDANDO,
          channelId:     this.channel.id,
        },
        { upsert: true },
      );

      if (this.interaction?.member) this.member = this.interaction.member;

      // Mensagem de boas-vindas com link do canal
      await this._envioCanal(thread, this._msgBoasVindas(thread.url));

      // UI de seleção de planos
      await this._exibirUI();
    } catch (e) {
      this.consoleError('criarCarrinho:', e);
    }
  }

  _restaurarExistente(doc) {
    this.cartId       = doc.id;
    this.quantity     = doc.quantity ?? 1;
    this.selectedPlan = doc.selectedPlan;
    if (this.selectedPlan) {
      this.days = PLANO_DIAS[this.selectedPlan] ?? 30;
    } else {
      this.days = 30;
    }
  }

  /**
   * Montagem da mensagem de boas-vindas com link do canal (thread).
   */
  _msgBoasVindas(canaisUrl) {
    return {
      content: '',
      embeds: [
        new EmbedBuilder()
          .setTitle(`🛒 Olá, ${this.user.username}! Seu carrinho foi preparado.`)
          .setDescription([
            `Você está prestes a adquirir **${this.productData.productName}`,
            '— um sistema exclusivo da **Nyox Applications** com a melhor qualidade do mercado. ✅',
            '',
            `Para ser redirecionado ao seu carrinho, clique no botão abaixo 👇`,
          ]),
          .setColor('#060A18'),
      ],
      components: [
        new ActionRowBuilder().addComponents(
          new ButtonBuilder()
            .setEmoji('🛒')
            .setLabel('Abrir Carrinho')
            .setStyle(ButtonStyle.Link)
            .setURL(canaisUrl),
        ),
      ],
    };
  }

  // ==================================================================
  // 2) SELEÇÃO DE PLANO
  // ==================================================================

  /**
   * Trata a seleção de plano (via clique no botão ou parâmetro forçado).
   * @param {Discord.Interaction} interaction
   * @param {string|null} forcarPlano - plano forçado (ex: "30DiasCart")
   */
  async tratarSelecaoDePlano(int = null, forcarPlano = null) {
    try {
      const codigo = forcarPlano ?? (int?.customId ?? null);
      if (!codigo) return; // sem plano informado, ignora

      let planoKey, dias;
      switch (codigo) {
        case '7DiasCart':    planoKey = 'semanal';    dias = 7;    break;
        case '15DiasCart':  planoKey = 'quizena';    dias = 15;   break;
        case '30DiasCart':  planoKey = 'mensal';     dias = 30;   break;
        default: return; // plano desconhecido
      }

      this._garantirPlano(planoKey);
      this.selectedPlan = planoKey;
      this.days = dias;

      // Persiste carrinho (atualiza qty e plano no mesmo documento)
      await Cart.updateOne(
        { channelId: this.channel.id },
        { quantity: this.quantity, selectedPlan: planoKey },
        { upsert: true },
      );

      await this._exibirUI();

      await this.sendLog(
        new EmbedBuilder()
          .setTitle('🧾 Log — Nova seleção de plano')
          .addFields(
            { name: '👥 Usuário',   value: this.user.username, inline: false },
            { name: '🛒 Plano',      value: `${planoKey} (${dias} dias)`, inline: false },
            { name: '🕐 Horário',    value: new Date().toLocaleString('pt-BR'), inline: false },
          ),
        { titulo: 'Seleção de plano' },
      );

      this._agendarInatividade(() => this.handleInatividade(), CFG.INACTIVITY_DELAY_SEC);
    } catch (e) {
      this.consoleError('tratarSelecaoDePlano:', e);
    }
  }

  // ==================================================================
  // 3) QUANTIDADE DE ITENS
  // ==================================================================

  /**
   * Adiciona ou remove um item do carrinho.
   */
  async alterarQuantidade(int, acao) {
    try {
      const ch = await this._resolverCanal();
      if (!ch) return; // sem canal ativo — operação inviável

      if (acao === 'add') {
        if (this.quantity < 50) {
          this.quantity += 1;
        }
      } else { // 'remove'
        if (this.quantity > 1) {
          this.quantity -= 1;
          await int.reply?.({
            embeds: [new EmbedBuilder().setDescription('➖ Item removido do carrinho. 🛒').setEmoji('🛒')],
            ephemeral: true,
          }).catch(() => {});
        } else {
          await int.reply?.({
            embeds: [new EmbedBuilder().setDescription('❌ Não é possível remover todos os itens do carrinho.', { ephemeral: true })],
            components: [],
          }).catch(() => {});
          return;
        }
      }

      await Cart.updateOne({ channelId: this.channel.id }, { quantity: this.quantity }, { upsert: true });
      await this._exibirUI();
      this._agendarInatividade(() => this.handleInatividade(), CFG.INACTIVITY_DELAY_SEC);
    } catch (e) {
      this.consoleError('alterarQuantidade:', e);
    }
  }

  // ==================================================================
  // 4) FINALIZAÇÃO DA COMPRA
  // ==================================================================

  /**
   * Finaliza o carrinho e gera o pagamento no gateway.
   */
  async finalizarCompra(int) {
    let jaDeferiu = false;
    let errCapturada = false;

    try {
      // Defer garante que não haverá edits conflitantes na interação
      if (!jaDeferiu) { jaDeferiu = true; await int.deferUpdate().catch(() => {}); }

      const ch = await this._resolverCanal();
      if (!ch || this._deleted) throw new Error('Carrinho inválido ou já encerrado.');

      // Valida integridade do carrinho
      const cart = await Cart.findOne({ channelId: this.channel.id });
      if (!cart) throw new Error('Carrinho não localizado.');
      if (cart.status !== STATUS_CART.AGUARDANDO) {
        throw new Error(`Carrinho em estado inesperado: ${cart.status}`);
      }
      if (cart.paymentId) {
        throw new Error('Já existe um pagamento em processamento — aguarde.');
      }

      const p   = this.productData.preco;
      this._garantirPlano(this.selectedPlan);

      const precoUnit = Number(p[this.selectedPlan].preco);
      if (precoUnit <= 0) throw new Error('Preço do plano não configurado.');

      const qtd     = Math.max(1, Math.min(50, this.quantity));
      const total   = precoUnit * qtd;
      const cents   = Math.round(total * 100); // converte para centavos
      if (!Number.isInteger(cents) || cents <= 0) throw new Error('Cálculo de valor inválido.');

      const opcoes = {
        amount:        cents,
        description:   `Pedido — ${this.user.username} (${this.selectedPlan} / ${this.days} dias)`,
        first_name:    this.user.first_name ?? 'Cliente',
        email:         this.user.email ?? 'pagamentos@nyox.tech',
        currency:      'BRL',
        otherData: {
          product_id:       this.targetProductId,
          cart_id:          this.cartId,
          plan:             this.selectedPlan,
          days:             this.days,
          quantity:         qtd,
          notification_url: this.interaction?.guild?.webhookURL || 'https://nyox.tech/api/notifications',
        },
      };

      // ── Cria o pagamento ──
      const paymentResponse = await this.processor.getPayment(92690421680); // ⚙️ substitua pela sua chave/token
      if (!paymentResponse) throw new Error('Gateway recusou a criação do pagamento.');

      this.pendingPaymentId = paymentResponse.id;

      // Persiste os modelos
      const pagamento = new Payment({
        payment_id:         paymentResponse.id,
        transaction_amount: cents,
        description:        opcoes.description,
        customer_id:        this.user.id,
        email:              opcoes.email,
        status:             'Pendente',
      });
      await pagamento.save();

      await Cart.updateOne({ channelId: this.channel.id }, { paymentId: this.pendingPaymentId }, { upsert: true });

      consoleInfo('[CART] Pagamento gerado:', paymentResponse.id);

      // ── Monitoramento em background ──
      const cleanupMonitor = await this._comecarMonitoramentoDePagamento(paymentResponse.id, opcoes);

      // (nenhuma outra chamada depende mais da interação aqui)

    } catch (e) {
      if (!jaDeferiu) {
        try {
          await int.reply({ content: 'Ops! Algo deu errado no processamento. Você pode tentar novamente mais tarde. 🙏', ephemeral: true }).catch(() => {});
        } catch (_) {}
      }

      errCapturada = true;
      await this._avisoCanal(ch ?? null, `❌ Erro ao finalizar o pedido\n_${e.message.split('\n')[0]}_`);
      this.consoleError('finalizarCompra:', e);
    }

    if (errCapturada && this.interaction) {
      // Nota: após deferUpdate() não é possível responder a interação novamente;
      // feedback adicional deve vir pela mensagem do canal (já enviada acima).
    }
  }

  /**
   * Gera o pagamento usando o PaymentProcessor já referenciado nesta instância.
   */
  async processarPagamento(opts) {
    // Fica aqui apenas para casos futuros que precisem reaproveitar as opções;
    // atualmente a finalizeCompra chama direto this.processor.getPayment(...)
    const resp = await this.processor.getPayment(opts.amount);
    if (!resp) return null;
    return resp;
  }

  // ==================================================================
  // 5) MONITORAMENTO DO PAGAMENTO
  // ==================================================================

  /**
   * Entra em loop verificando o status do pagamento até:
   * - aprovado  → trata aprovação
   * - cancelado → trata cancelamento
   * - timeout   → marca para revisão manual
   * Retorna uma função de limpeza do intervalo (chamar no fim do fluxo).
   */
  async _comecarMonitoramentoDePagamento(id, opts) {
    const aceitos   = ['approved', 'paid', 'success']; // ⚙️ ajuste conforme os estados válidos do seu gateway
    const cancelados = ['cancelled', 'refunded', 'expired']; // ⚙️ idem

    let tentativasValidas  = 0;
    let falhasDoGateway   = 0;
    const intervalo       = CFG.POLL_INTERVAL_MS;
    const maxTentativas   = CFG.POLL_MAX_TRIES;
    const falhasMaximas   = 7; // se o gateway ficar cair muito, marca pra revisão manual

    const checar = async () => {
      try {
        let raw;
        try {
          raw = await this.processor.checkPaymentStatus(id);
        } catch (gatewayErr) {
          falhasDoGateway++;
          this.consoleWarn(`Checagem falhou (gateway fora do ar):`, gatewayErr.message);
          if (falhasDoGateway >= falhasMaximas) {
            // Gateway completamente indisponível — para o monitor e sinaliza revisão manual
            await Cart.updateOne({ channelId: this.channel.id }, { status: 'Falha_na_verificacao' }, { upsert: true }).catch(() => {});
            this.consoleWarn('Gateway de pagamentos indisponível por muitas tentativas — carrinho marcado para revisão manual.');
            return;
          }
          await sleep(intervalo);
          return;
        }

        const status = raw instanceof Promise ? await raw : raw;

        if (aceitos.includes(status)) {
          clearInterval(monInt);
          await this.tratarAprovacao(id, opts);
          return;
        }
        if (cancelados.includes(status)) {
          clearInterval(monInt);
          await this.tratarCancelamento(id, null, { customId: 'gateway' });
          return;
        }

        tentativasValidas++;
        if (tentativasValidas >= maxTentativas) {
          await Cart.updateOne({ channelId: this.channel.id }, { status: 'Falha_na_verificacao' }, { upsert: true }).catch(() => {});
          this.consoleWarn(`Após ${maxTentativas} tentativas sem status reconhecido — ficará pendente para verificação manual.`);
          return;
        }

        if (falhasDoGateway >= falhasMaximas) {
          await Cart.updateOne({ channelId: this.channel.id }, { status: 'Falha_na_verificacao' }, { upsert: true }).catch(() => {});
          return;
        }

        await sleep(intervalo);
      } catch (e) {
        falhasDoGateway++;
        this.consoleWarn(`Checagem de status (${id}) falhou:`, e.message);
        await sleep(intervalo);
      }
    };

    const monInt = setInterval(checar, intervalo);
    setTimeout(checar, 5000); // primeira checagem após 5s (evita colisão com respostas imediatas)

    return () => clearInterval(monInt);
  }

  /**
   * Lida com pagamento aprovado: aplica cargo, limpa mensagens e envia instruções de resgate.
   */
  async tratarAprovacao(id, opts) {
    try {
      const cart = await Cart.findOne({ channelId: this.channel.id });

      if (!cart) {
        this.consoleInfo(`[${id}] Sem carrinho associado — ignorando.`);
        return;
      }
      if (cart.status === STATUS_CART.PAGO || cart.status === STATUS_CART.CANCELADO) {
        this.consoleInfo(`[${id}] Carrinho já finalizado — ignorando.`);
        return;
      }
      if (cart.paymentId === id) {
        this.consoleInfo(`[${id}] Pagamento duplicado — ignorando.`);
        return;
      }

      // Marca como pago e atualiza
      cart.status = STATUS_CART.PAGO;
      cart.updatedAt = new Date();
      await cart.save();

      // ── Aplica cargo de comprador ──
      const membro = await this._resolverMembro();
      const cid = CFG.CARGO_CLIENT_ID;
      if (membro && cid) {
        try {
          await membro.roles.add({ id: cid }).catch(err => {
            if (err.code === 100052 || err.code === 500130) return; // member não encontrado / sem roles
            this.consoleWarn(`Falha ao adicionar role (${cid}):`, err.message);
          });
        } catch (e) {
          this.consoleWarn(`Erro ao aplicar role (${cid}):`, e.message);
        }
      }

      // ── Canal do carrinho ──
      const ch = await this._resolverCanal();
      if (!ch) {
        this.consoleWarn(`[${id}] Canal sumiu — limpando registros.`);
        try { await Cart.deleteOne({ channelId: this.channel.id }).catch(() => {}); } catch (_) {}
        return;
      }

      // Apaga mensagens extras preservando as 2 primeiras (aviso + instruções)
      try {
        const ids = await ch.messages.ids({ limit: 100 });
        if (ids.length > 2) {
          await ch.bulkDelete(ids.slice(2, Math.min(ids.length, 52))).catch(() => {});
        }
      } catch (_) {}

      // ── Mensagem final ──
      const dias = this.days;
      const finalEmbed = new EmbedBuilder()
        .setTitle('✅ Pagamento Aprovado! 🎉')
        .setDescription([
          `Parabéns, **${this.user.username}**! Seu pagamento foi aprovado. ✅`,
          '',
          `🆔 **ID da compra:** \`${this.cartId}\``,
          '',
          'Para ativarmos sua aplicação, precisamos de 3 informações:\n' +
          '1. Nome que você deseja na aplicação\n' +
          '2. ID que será usado como dono do bot\n' +
          '3. ⚠️ **Token do bot** — mantenha bem seguro, não compartilhe!',
        ]);

      const linhaResgate = new ActionRowBuilder().addComponents(
        new ButtonBuilder()
          .setEmoji('🤖')
          .setLabel('🎉 Receber Bot')
          .setStyle(ButtonStyle.Primary)
          .setCustomId(`redeemBot-${this.selectedPlan}-${dias}-REDEEM`), // ⚙️ padrão consumido pelo backend
        new ButtonBuilder()
          .setEmoji('📜')
          .setLabel('📘 Portal do Desenvolvedor')
          .setStyle(ButtonStyle.Link)
          .setURL('https://discord.com/developers/applications/')
          .setCustomId('portalDev'),
        new ButtonBuilder()
          .setEmoji('📖')
          .setLabel('🔗 Tutorial')
          .setStyle(ButtonStyle.Link)
          .setURL('https://docs.nyox.tech/tutorials/createapp'),
      );

      await this._envioCanal(ch, { embeds: [finalEmbed], components: [linhaResgate] });

      await this.sendLog(
        new EmbedBuilder()
          .setTitle('🧾 [LOG] Pagamento aprovado')
          .addFields(
            { name: '👥 Usuário', value: this.user.username, inline: false },
            { name: '🛒 Produto', value: this.productData.productName, inline: false },
            { name: '💳 Payment ID', value: id, inline: false },
            { name: '🕐 Horário', value: new Date().toLocaleString('pt-BR'), inline: false },
          ),
        { titulo: 'Aprovação' },
      );
    } catch (e) {
      this.consoleError('tratarAprovacao:', e);
    }
  }

  /**
   * Trata cancelamentos (por botão do usuário ou expiração pelo gateway).
   */
  async tratarCancelamento(id = null, interacao = null, origem = null) {
    try {
      // Tenta cancelar pagamento pendente via gateway (se houver)
      const cart = await Cart.findOne({ channelId: this.channel.id });
      if (cart && cart.paymentId && cart.status !== STATUS_CART.PAGO && cart.status !== STATUS_CANCELADO) {
        try {
          await this.processor.cancelPayment(cart.paymentId).catch(() => {});
        } catch (e) {
          this.consoleWarn(`Não foi possível cancelar o pagamento via gateway (${cart.paymentId}):`, e.message);
        }
      }

      const log = new EmbedBuilder()
        .setTitle('🧾 Sistema de Logs — Carrinho Encerrado')
        .setAuthor({ name: this.client.user.username, iconURL: this.client.user.displayAvatarURL({ dynamic: true }) })
        .setFooter({
          text: (interacao?.guild?.name ?? '—'),
          iconURL: interacao?.guild?.iconURL?.({ dynamic: true }) ?? '>',
        })
        .addFields(
          { name: '👥 Usuário', value: `${this.user.username} #${this.user.id}`, inline: false },
          { name: '🛒 Produto', value: this.productData?.productName ?? '—', inline: false },
          { name: '🗂️ Carrinho', value: `\`${this.cartId}\``, inline: false },
          { name: '❔ Motivo',
            value: origem === 'gateway'
              ? 'Pagamento expirado/cancelado automaticamente'
              : interacao?.customId === 'cancelPayment'
                ? 'Cancelamento explícito do pagamento'
                : 'Cancelamento do pedido',
            inline: false },
          { name: '🕐 Horário', value: new Date().toLocaleString('pt-BR'), inline: false },
        );

      await this.sendLog(log, { titulo: 'Cancelamento' });

      if (this.channel) {
        const ch = await this._resolverCanal();
        if (ch) {
          try {
            const ids = await ch.messages.ids({ limit: 100 });
            if (ids.length > 2) {
              await ch.bulkDelete(ids.slice(2, Math.min(ids.length, 52))).catch(() => {});
            }
            await ch.delete().catch(() => {});
          } catch (_) {}
        }
        try {
          await Cart.deleteOne({ channelId: this.channel.id }).catch(() => {});
        } catch (_) {}
      }
    } catch (e) {
      this.consoleError('tratarCancelamento:', e);
    }
  }

  // ==================================================================
  // 6) THREAD PRIVADA
  // ==================================================================

  /**
   * Cria uma thread privada restrita ao usuário (só ele pode escrever).
   */
  async _threadPrivado() {
    const canal = this.interaction?.channel;
    if (!canal) throw new Error('Interação sem canal disponível (use run() passando a interação).');

    return canal.threads.create({
      name:        `🛒・${this.user.username}・#${this.user.id}`,
      topic:       `Carrinho — ${this.productData.productName} (#${this.cartId})`,
      type:        ChannelType.PrivateThread,
      reason:      'Criação de carrinho de compras Nyox Applications',
      members:     [this.user.id],
      permissionOverwrites: [
        { id: this.user.id, allow: ['ViewChannel'], deny: [] },
        { id: this.interaction.guild.id, allow: [], deny: ['ViewChannel', 'SendMessages'] },
      ],
    });
  }

  // ==================================================================
  // 7) DETALHES DO PIX / QR CODE
  // ==================================================================

  /**
   * Envia o QR Code (arquivo) ou o código copia-e-cola do Pix para quem clicou.
   */
  async _enviarDetalhesPagamento(int) {
    try {
      if (!this.channel) {
        await int.reply({ content: '⚠️ Os dados de pagamento ainda não estão disponíveis.', ephemeral: true }).catch(() => {});
        return;
      }

      const cart = await Cart.findOne({ channelId: this.channel.id });
      if (!cart || !cart.paymentId) {
        await int.reply({ content: '⚠️ O pagamento ainda não foi gerado para este carrinho.', ephemeral: true }).catch(() => {});
        return;
      }

      const detalhe = await this.processor.getPayment(cart.paymentId).catch(() => null);
      if (!detalhe) {
        await int.reply({ content: '⚠️ Não foi possível recuperar os detalhes do pagamento.', ephemeral: true }).catch(() => {});
        return;
      }

      if (detalhe.attachment) {
        await int.reply({ files: [detalhe.attachment], ephemeral: true }).catch(() => {});
      } else if (detalhe.pixCopyPasteCode) {
        await int.reply({ content: detalhe.pixCopyPasteCode, ephemeral: true }).catch(() => {});
      } else {
        await int.reply({ content: '⚠️ Os detalhes de pagamento não estavam disponíveis.', ephemeral: true }).catch(() => {});
      }
    } catch (e) {
      this.consoleError('_enviarDetalhesPagamento:', e);
      try {
        await int.reply({ content: '⚠️ Ocorreu um erro ao enviar os dados do pagamento.', ephemeral: true }).catch(() => {});
      } catch (_) {}
    }
  }

  // ==================================================================
  // 8) RESGATE DO BOT (pós-aprovação)
  // ==================================================================

  /**
   * Fluxo de resgate após aprovação.
   * O backend deve identificar o padrão do customId:
   *   redeemBot-{mensal|quizena|semanal}-{dias}-{quantidade}-REDEEM
   * e aplicar as regras de negócio (cobrar nome, ownerID, token, etc.).
   */
  async executarRedeem(plan, dias, qtd, int) {
    try {
      await int.deferUpdate().catch(() => {}); // evita double-edit

      const membro = await this._resolverMembro();
      if (membro) {
        try {
          await membro.roles.add({ id: CFG.CARGO_CLIENT_ID }).catch(err => {
            if (err.code === 100052) return; // usuário saiu do servidor
            this.consoleWarn('Falha ao aplicar role de resgate:', err.message);
          });
        } catch (e) {
          this.consoleWarn('Erro ao adicionar role de resgate:', e.message);
        }
      }

      await int.reply({
        content: `✅ **Resgate registrado!** 🚀\n\nSuas informações foram salvas com sucesso.\nNossa equipe enviará as instruções finais pelo canal privado.\n\n*Caso este seja um teste, lembre-se de que a role de resgate é aplicada automaticamente.*`,
        ephemeral: true,
      }).catch(() => {});
    } catch (e) {
      this.consoleError('executarRedeem:', e);
    }
  }

  // ==================================================================
  // 9) COLETOR DE BOTÕES (RUNNER PRINCIPAL)
  // ==================================================================

  /**
   * Inicia o ciclo de vida completo: cria o carrinho + captura cliques de botões.
   * @param {Discord.Interaction} [initialInt] - interação inicial (passada do comando)
   */
  async run(initialInt = null) {
    try {
      let int = initialInt || this.interaction;

      // Captura a interação "viva" para cliques posteriores (dentro da thread)
      this.threadInteraction = int;

      await this.criarCarrinho();       // <-- cria/aproveita o carrinho

      const ch = this._resolverCanal();
      if (!ch) {
        this.consoleError('run(): nenhum canal disponível para configurar o coletor.');
        return;
      }

      // Whitelist dos comandos suportados (regex para IDs compostos de resgate)
      const CONHECIDOS = ['cartAdd', 'cartRemove', 'finalizePurchase', 'cancelOrder', 'cancelPayment', 'pixCopyPaste', 'qrCode'];
      const REG_REDEEM = /^redeemBot-(mensal|quizena|semanal)-\d+-\d+-REDEEM$/;

      const coletor = ch.createMessageComponentCollector({
        componentType: ComponentType.Button,
        time:          CFG.COLLECTOR_TIMEOUT_MS, // 10 min — sem cliques nesse tempo máximo
      });

      coletor.on('collect', async (btn) => {
        // Anti-abuso
        if (btn.user.id !== this.user.id) {
          try { await btn.deferUpdate().catch(() => {}); } catch (_) {}
          return;
        }

        this._limparTimer();
        this._agendarInatividade(() => this.handleInatividade(), CFG.INACTIVITY_DELAY_SEC);

        const codigo = btn.customId.toLowerCase();

        switch (codigo) {
          case 'cartAdd':
            await this.alterarQuantidade(btn, 'add');
            break;

          case 'cartRemove':
            {
              await btn.reply?.({
                embeds: [new EmbedBuilder().setDescription('➖ Item removido do carrinho. 🛒').setEmoji('🛒')],
                ephemeral: true,
              }).catch(() => {});
              await this.alterarQuantidade(btn, 'remove');
              break;
            }

          case 'finalizePurchase':
            await this.finalizarCompra(btn);
            break;

          case 'cancelOrder':
            // Cancela e limpa o carrinho (inclusive pagamento pendente, se houver)
            await this.tratarCancelamento(null, btn, 'usuario-cancel-order');
            break;

          case 'cancelPayment':
            await this.tratarCancelamento(null, btn, 'cancelPayment-botao');
            break;

          case 'pixCopyPaste':
          case 'qrCode':
            await this._enviarDetalhesPagamento(btn);
            break;

          // ── IDs compostos de resgate ──
          if (REG_REDEEM.test(codigo)) {
            const partes = codigo.split('-');
            if (partes.length >= 5
                && partes[0] === 'redeemBot'
                && partes[1] && (/^mensal$|^quizena$|^semanal$/.test(partes[1]))
                && /^\d+$/.test(partes[2]) && /^\d+$/.test(partes[3])
                && partes[4] === 'REDEEM') {
              await this.executarRedeem(partes[1], Number(partes[2]), Number(partes[3] || 1), btn);
            }
            break;
          }

          // Qualquer outro comando (typos, testes externos, etc.)
          try {
            await btn.reply({ content: '⚠️ Esse comando não está disponível neste momento.', ephemeral: true }).catch(() => {});
          } catch (_) {}
        }
      });

      coletor.on('end', async () => {
        this._limparTimer();
        try {
          await this.limparPendencias();
        } catch (e) {
          this.consoleError('coletor.on(end) › limparPendencias:', e);
        }
      });
    } catch (e) {
      this.consoleError('run():', e);
    }
  }

  /**
   * Varre carrinhos com pagamentos não confirmados e os cancela.
   * Chamado no timeout do coletor (e em situações de falha).
   */
  async limparPendencias() {
    const pendentes = await Cart.find({
      status: { $in: [STATUS_CART.AGUARDANDO, STATUS_CART.PROCESSANDO] },
    })
      .then(docs => docs.filter(d => d.paymentId && d.status !== STATUS_CART.PAGO && d.status !== STATUS_CART.CANCELADO))
      .catch(() => []);

    for (const c of pendentes) {
      try {
        if (c.paymentId) {
          try {
            await this.processor.cancelPayment(c.paymentId).catch(() => {});
          } catch (e) {
            this.consoleWarn(`Falha ao cancelar payment ${c.paymentId}:`, e.message);
          }
        }
        await Cart.updateOne({ channelId: c.channelId }, { status: STATUS_CART.CANCELADO, updatedAt: new Date() }, { upsert: true }).catch(() => {});
      } catch (e) {
        this.consoleWarn(`Erro ao limpar carrinho ${c.id}:`, e.message);
      }
    }
  }

  // ==================================================================
  // FIM DA CLASSE
  // ==================================================================
}

module.exports = CartClass;
