    if (errCapturada && this.interaction) {
      // Nota: após deferUpdate() não é possível responder a interação novamente;
      // feedback adicional deve vir pela mensagem do canal (já enviada acima).
    }
  }

  /**
   * Gera o pagamento usando o PaymentProcessor já referenciado nesta instância.
   */
  async processarPagamento(opts) {
    // Fica aqui apenas para casos futuros que precisem reaproveitar as opções;
    // atualmente a finalizeCompra chama direto this.processor.getPayment(...)
    const resp = await this.processor.getPayment(opts.amount);
    if (!resp) return null;
    return resp;
  }

  // ==================================================================
  // 5) MONITORAMENTO DO PAGAMENTO
  // ==================================================================

  /**
   * Entra em loop verificando o status do pagamento até:
   * - aprovado  → trata aprovação
   * - cancelado → trata cancelamento
   * - timeout   → marca para revisão manual
   * Retorna uma função de limpeza do intervalo (chamar no fim do fluxo).
   */
  async _comecarMonitoramentoDePagamento(id, opts) {
    const aceitos   = ['approved', 'paid', 'success']; // ⚙️ ajuste conforme os estados válidos do seu gateway
    const cancelados = ['cancelled', 'refunded', 'expired']; // ⚙️ idem

    let tentativasValidas  = 0;
    let falhasDoGateway   = 0;
    const intervalo       = CFG.POLL_INTERVAL_MS;
    const maxTentativas   = CFG.POLL_MAX_TRIES;
    const falhasMaximas   = 7; // se o gateway ficar cair muito, marca pra revisão manual

    const checar = async () => {
      try {
        let raw;
        try {
          raw = await this.processor.checkPaymentStatus(id);
        } catch (gatewayErr) {
          falhasDoGateway++;
          this.consoleWarn(`Checagem falhou (gateway fora do ar):`, gatewayErr.message);
          if (falhasDoGateway >= falhasMaximas) {
            // Gateway completamente indisponível — para o monitor e sinaliza revisão manual
            await Cart.updateOne({ channelId: this.channel.id }, { status: 'Falha_na_verificacao' }, { upsert: true }).catch(() => {});
            this.consoleWarn('Gateway de pagamentos indisponível por muitas tentativas — carrinho marcado para revisão manual.');
            return;
          }
          await sleep(intervalo);
          return;
        }

        const status = raw instanceof Promise ? await raw : raw;

        if (aceitos.includes(status)) {
          clearInterval(monInt);
          await this.tratarAprovacao(id, opts);
          return;
        }
        if (cancelados.includes(status)) {
          clearInterval(monInt);
          await this.tratarCancelamento(id, null, { customId: 'gateway' });
          return;
        }

        tentativasValidas++;
        if (tentativasValidas >= maxTentativas) {
          await Cart.updateOne({ channelId: this.channel.id }, { status: 'Falha_na_verificacao' }, { upsert: true }).catch(() => {});
          this.consoleWarn(`Após ${maxTentativas} tentativas sem status reconhecido — ficará pendente para verificação manual.`);
          return;
        }

        if (falhasDoGateway >= falhasMaximas) {
          await Cart.updateOne({ channelId: this.channel.id }, { status: 'Falha_na_verificacao' }, { upsert: true }).catch(() => {});
          return;
        }

        await sleep(intervalo);
      } catch (e) {
        falhasDoGateway++;
        this.consoleWarn(`Checagem de status (${id}) falhou:`, e.message);
        await sleep(intervalo);
      }
    };

    const monInt = setInterval(checar, intervalo);
    setTimeout(checar, 5000); // primeira checagem após 5s (evita colisão com respostas imediatas)

    return () => clearInterval(monInt);
  }

  /**
   * Lida com pagamento aprovado: aplica cargo, limpa mensagens e envia instruções de resgate.
   */
  async tratarAprovacao(id, opts) {
    try {
      const cart = await Cart.findOne({ channelId: this.channel.id });

      if (!cart) {
        this.consoleInfo(`[${id}] Sem carrinho associado — ignorando.`);
        return;
      }
      if (cart.status === STATUS_CART.PAGO || cart.status === STATUS_CART.CANCELADO) {
        this.consoleInfo(`[${id}] Carrinho já finalizado — ignorando.`);
        return;
      }
      if (cart.paymentId === id) {
        this.consoleInfo(`[${id}] Pagamento duplicado — ignorando.`);
        return;
      }

      // Marca como pago e atualiza
      cart.status = STATUS_CART.PAGO;
      cart.updatedAt = new Date();
      await cart.save();

      // ── Aplica cargo de comprador ──
      const membro = await this._resolverMembro();
      const cid = CFG.CARGO_CLIENT_ID;
      if (membro && cid) {
        try {
          await membro.roles.add({ id: cid }).catch(err => {
            if (err.code === 100052 || err.code === 500130) return; // member não encontrado / sem roles
            this.consoleWarn(`Falha ao adicionar role (${cid}):`, err.message);
          });
        } catch (e) {
          this.consoleWarn(`Erro ao aplicar role (${cid}):`, e.message);
        }
      }

      // ── Canal do carrinho ──
      const ch = await this._resolverCanal();
      if (!ch) {
        this.consoleWarn(`[${id}] Canal sumiu — limpando registros.`);
        try { await Cart.deleteOne({ channelId: this.channel.id }).catch(() => {}); } catch (_) {}
        return;
      }

      // Apaga mensagens extras preservando as 2 primeiras (aviso + instruções)
      try {
        const ids = await ch.messages.ids({ limit: 100 });
        if (ids.length > 2) {
          await ch.bulkDelete(ids.slice(2, Math.min(ids.length, 52))).catch(() => {});
        }
      } catch (_) {}

      // ── Mensagem final ──
      const dias = this.days;
      const finalEmbed = new EmbedBuilder()
        .setTitle('✅ Pagamento Aprovado! 🎉')
        .setDescription([
          `Parabéns, **${this.user.username}**! Seu pagamento foi aprovado. ✅`,
          '',
          `🆔 **ID da compra:** \`${this.cartId}\``,
          '',
          'Para ativarmos sua aplicação, precisamos de 3 informações:\n' +
          '1. Nome que você deseja na aplicação\n' +
          '2. ID que será usado como dono do bot\n' +
          '3. ⚠️ **Token do bot** — mantenha bem seguro, não compartilhe!',
        ]);

      const linhaResgate = new ActionRowBuilder().addComponents(
        new ButtonBuilder()
          .setEmoji('🤖')
          .setLabel('🎉 Receber Bot')
          .setStyle(ButtonStyle.Primary)
          .setCustomId(`redeemBot-${this.selectedPlan}-${dias}-REDEEM`), // ⚙️ padrão consumido pelo backend
        new ButtonBuilder()
          .setEmoji('📜')
          .setLabel('📘 Portal do Desenvolvedor')
          .setStyle(ButtonStyle.Link)
          .setURL('https://discord.com/developers/applications/')
          .setCustomId('portalDev'),
        new ButtonBuilder()
          .setEmoji('📖')
          .setLabel('🔗 Tutorial')
          .setStyle(ButtonStyle.Link)
          .setURL('https://docs.nyox.tech/tutorials/createapp'),
      );

      await this._envioCanal(ch, { embeds: [finalEmbed], components: [linhaResgate] });

      await this.sendLog(
        new EmbedBuilder()
          .setTitle('🧾 [LOG] Pagamento aprovado')
          .addFields(
            { name: '👥 Usuário', value: this.user.username, inline: false },
            { name: '🛒 Produto', value: this.productData.productName, inline: false },
            { name: '💳 Payment ID', value: id, inline: false },
            { name: '🕐 Horário', value: new Date().toLocaleString('pt-BR'), inline: false },
          ),
        { titulo: 'Aprovação' },
      );
    } catch (e) {
      this.consoleError('tratarAprovacao:', e);
    }
  }

  /**
   * Trata cancelamentos (por botão do usuário ou expiração pelo gateway).
   */
  async tratarCancelamento(id = null, interacao = null, origem = null) {
    try {
      // Tenta cancelar pagamento pendente via gateway (se houver)
      const cart = await Cart.findOne({ channelId: this.channel.id });
      if (cart && cart.paymentId && cart.status !== STATUS_CART.PAGO && cart.status !== STATUS_CANCELADO) {
        try {
          await this.processor.cancelPayment(cart.paymentId).catch(() => {});
        } catch (e) {
          this.consoleWarn(`Não foi possível cancelar o pagamento via gateway (${cart.paymentId}):`, e.message);
        }
      }

      const log = new EmbedBuilder()
        .setTitle('🧾 Sistema de Logs — Carrinho Encerrado')
        .setAuthor({ name: this.client.user.username, iconURL: this.client.user.displayAvatarURL({ dynamic: true }) })
        .setFooter({
          text: (interacao?.guild?.name ?? '—'),
          iconURL: interacao?.guild?.iconURL?.({ dynamic: true }) ?? '>',
        })
        .addFields(
          { name: '👥 Usuário', value: `${this.user.username} #${this.user.id}`, inline: false },
          { name: '🛒 Produto', value: this.productData?.productName ?? '—', inline: false },
          { name: '🗂️ Carrinho', value: `\`${this.cartId}\``, inline: false },
          { name: '❔ Motivo',
            value: origem === 'gateway'
              ? 'Pagamento expirado/cancelado automaticamente'
              : interacao?.customId === 'cancelPayment'
                ? 'Cancelamento explícito do pagamento'
                : 'Cancelamento do pedido',
            inline: false },
          { name: '🕐 Horário', value: new Date().toLocaleString('pt-BR'), inline: false },
        );

      await this.sendLog(log, { titulo: 'Cancelamento' });

      if (this.channel) {
        const ch = await this._resolverCanal();
        if (ch) {
          try {
            const ids = await ch.messages.ids({ limit: 100 });
            if (ids.length > 2) {
              await ch.bulkDelete(ids.slice(2, Math.min(ids.length, 52))).catch(() => {});
            }
            await ch.delete().catch(() => {});
          } catch (_) {}
        }
        try {
          await Cart.deleteOne({ channelId: this.channel.id }).catch(() => {});
        } catch (_) {}
      }
    } catch (e) {
      this.consoleError('tratarCancelamento:', e);
    }
  }

  // ==================================================================
  // 6) THREAD PRIVADA
  // ==================================================================

  /**
   * Cria uma thread privada restrita ao usuário (só ele pode escrever).
   */
  async _threadPrivado() {
    const canal = this.interaction?.channel;
    if (!canal) throw new Error('Interação sem canal disponível (use run() passando a interação).');

    return canal.threads.create({
      name:        `🛒・${this.user.username}・#${this.user.id}`,
      topic:       `Carrinho — ${this.productData.productName} (#${this.cartId})`,
      type:        ChannelType.PrivateThread,
      reason:      'Criação de carrinho de compras Nyox Applications',
      members:     [this.user.id],
      permissionOverwrites: [
        { id: this.user.id, allow: ['ViewChannel'], deny: [] },
        { id: this.interaction.guild.id, allow: [], deny: ['ViewChannel', 'SendMessages'] },
      ],
    });
  }

  // ==================================================================
  // 7) DETALHES DO PIX / QR CODE
  // ==================================================================

  /**
   * Envia o QR Code (arquivo) ou o código copia-e-cola do Pix para quem clicou.
   */
  async _enviarDetalhesPagamento(int) {
    try {
      if (!this.channel) {
        await int.reply({ content: '⚠️ Os dados de pagamento ainda não estão disponíveis.', ephemeral: true }).catch(() => {});
        return;
      }

      const cart = await Cart.findOne({ channelId: this.channel.id });
      if (!cart || !cart.paymentId) {
        await int.reply({ content: '⚠️ O pagamento ainda não foi gerado para este carrinho.', ephemeral: true }).catch(() => {});
        return;
      }

      const detalhe = await this.processor.getPayment(cart.paymentId).catch(() => null);
      if (!detalhe) {
        await int.reply({ content: '⚠️ Não foi possível recuperar os detalhes do pagamento.', ephemeral: true }).catch(() => {});
        return;
      }

      if (detalhe.attachment) {
        await int.reply({ files: [detalhe.attachment], ephemeral: true }).catch(() => {});
      } else if (detalhe.pixCopyPasteCode) {
        await int.reply({ content: detalhe.pixCopyPasteCode, ephemeral: true }).catch(() => {});
      } else {
        await int.reply({ content: '⚠️ Os detalhes de pagamento não estavam disponíveis.', ephemeral: true }).catch(() => {});
      }
    } catch (e) {
      this.consoleError('_enviarDetalhesPagamento:', e);
      try {
        await int.reply({ content: '⚠️ Ocorreu um erro ao enviar os dados do pagamento.', ephemeral: true }).catch(() => {});
      } catch (_) {}
    }
  }

  // ==================================================================
  // 8) RESGATE DO BOT (pós-aprovação)
  // ==================================================================

  /**
   * Fluxo de resgate após aprovação.
   * O backend deve identificar o padrão do customId:
   *   redeemBot-{mensal|quizena|semanal}-{dias}-{quantidade}-REDEEM
   * e aplicar as regras de negócio (cobrar nome, ownerID, token, etc.).
   */
  async executarRedeem(plan, dias, qtd, int) {
    try {
      await int.deferUpdate().catch(() => {}); // evita double-edit

      const membro = await this._resolverMembro();
      if (membro) {
        try {
          await membro.roles.add({ id: CFG.CARGO_CLIENT_ID }).catch(err => {
            if (err.code === 100052) return; // usuário saiu do servidor
            this.consoleWarn('Falha ao aplicar role de resgate:', err.message);
          });
        } catch (e) {
          this.consoleWarn('Erro ao adicionar role de resgate:', e.message);
        }
      }

      await int.reply({
        content: `✅ **Resgate registrado!** 🚀\n\nSuas informações foram salvas com sucesso.\nNossa equipe enviará as instruções finais pelo canal privado.\n\n*Caso este seja um teste, lembre-se de que a role de resgate é aplicada automaticamente.*`,
        ephemeral: true,
      }).catch(() => {});
    } catch (e) {
      this.consoleError('executarRedeem:', e);
    }
  }

  // ==================================================================
  // 9) COLETOR DE BOTÕES (RUNNER PRINCIPAL)
  // ==================================================================

  /**
   * Inicia o ciclo de vida completo: cria o carrinho + captura cliques de botões.
   * @param {Discord.Interaction} [initialInt] - interação inicial (passada do comando)
   */
  async run(initialInt = null) {
    try {
      let int = initialInt || this.interaction;

      // Captura a interação "viva" para cliques posteriores (dentro da thread)
      this.threadInteraction = int;

      await this.criarCarrinho();       // <-- cria/aproveita o carrinho

      const ch = this._resolverCanal();
      if (!ch) {
        this.consoleError('run(): nenhum canal disponível para configurar o coletor.');
        return;
      }

      // Whitelist dos comandos suportados (regex para IDs compostos de resgate)
      const CONHECIDOS = ['cartAdd', 'cartRemove', 'finalizePurchase', 'cancelOrder', 'cancelPayment', 'pixCopyPaste', 'qrCode'];
      const REG_REDEEM = /^redeemBot-(mensal|quizena|semanal)-\d+-\d+-REDEEM$/;

      const coletor = ch.createMessageComponentCollector({
        componentType: ComponentType.Button,
        time:          CFG.COLLECTOR_TIMEOUT_MS, // 10 min — sem cliques nesse tempo máximo
      });

      coletor.on('collect', async (btn) => {
        // Anti-abuso
        if (btn.user.id !== this.user.id) {
          try { await btn.deferUpdate().catch(() => {}); } catch (_) {}
          return;
        }

        this._limparTimer();
        this._agendarInatividade(() => this.handleInatividade(), CFG.INACTIVITY_DELAY_SEC);

        const codigo = btn.customId.toLowerCase();

        switch (codigo) {
          case 'cartAdd':
            await this.alterarQuantidade(btn, 'add');
            break;

          case 'cartRemove':
            {
              await btn.reply?.({
                embeds: [new EmbedBuilder().setDescription('➖ Item removido do carrinho. 🛒').setEmoji('🛒')],
                ephemeral: true,
              }).catch(() => {});
              await this.alterarQuantidade(btn, 'remove');
              break;
            }

          case 'finalizePurchase':
            await this.finalizarCompra(btn);
            break;

          case 'cancelOrder':
            // Cancela e limpa o carrinho (inclusive pagamento pendente, se houver)
            await this.tratarCancelamento(null, btn, 'usuario-cancel-order');
            break;

          case 'cancelPayment':
            await this.tratarCancelamento(null, btn, 'cancelPayment-botao');
            break;

          case 'pixCopyPaste':
          case 'qrCode':
            await this._enviarDetalhesPagamento(btn);
            break;

          // ── IDs compostos de resgate ──
          if (REG_REDEEM.test(codigo)) {
            const partes = codigo.split('-');
            if (partes.length >= 5
                && partes[0] === 'redeemBot'
                && partes[1] && (/^mensal$|^quizena$|^semanal$/.test(partes[1]))
                && /^\d+$/.test(partes[2]) && /^\d+$/.test(partes[3])
                && partes[4] === 'REDEEM') {
              await this.executarRedeem(partes[1], Number(partes[2]), Number(partes[3] || 1), btn);
            }
            break;
          }

          // Qualquer outro comando (typos, testes externos, etc.)
          try {
            await btn.reply({ content: '⚠️ Esse comando não está disponível neste momento.', ephemeral: true }).catch(() => {});
          } catch (_) {}
        }
      });

      coletor.on('end', async () => {
        this._limparTimer();
        try {
          await this.limparPendencias();
        } catch (e) {
          this.consoleError('coletor.on(end) › limparPendencias:', e);
        }
      });
    } catch (e) {
      this.consoleError('run():', e);
    }
  }

  /**
   * Varre carrinhos com pagamentos não confirmados e os cancela.
   * Chamado no timeout do coletor (e em situações de falha).
   */
  async limparPendencias() {
    const pendentes = await Cart.find({
      status: { $in: [STATUS_CART.AGUARDANDO, STATUS_CART.PROCESSANDO] },
    })
      .then(docs => docs.filter(d => d.paymentId && d.status !== STATUS_CART.PAGO && d.status !== STATUS_CART.CANCELADO))
      .catch(() => []);

    for (const c of pendentes) {
      try {
        if (c.paymentId) {
          try {
            await this.processor.cancelPayment(c.paymentId).catch(() => {});
          } catch (e) {
            this.consoleWarn(`Falha ao cancelar payment ${c.paymentId}:`, e.message);
          }
        }
        await Cart.updateOne({ channelId: c.channelId }, { status: STATUS_CART.CANCELADO, updatedAt: new Date() }, { upsert: true }).catch(() => {});
      } catch (e) {
        this.consoleWarn(`Erro ao limpar carrinho ${c.id}:`, e.message);
      }
    }
  }

  // ==================================================================
  // FIM DA CLASSE
  // ==================================================================
}

module.exports = CartClass;
```

