_asyncPollPayment(id, accepted, cancelled, intervalMs, maxTries) {
  let attempts = 0;
  while (attempts < maxTries) {
    try {
      const status = await this.paymentProcessor.checkPaymentStatus(id); // assume método existe
      if (accepted.includes(status)) { this._emitApproval(id); break; }
      if (cancelled.includes(status)) { this._emitCancellation(id); break; }
      attempts++;
      await sleep(intervalMs);
    } catch (e) {
      this._error(`Verificação de pagamento falhou (tenta ${attempts}/${maxTries}):`, e);
      await sleep(intervalMs);
    }
  }
  if (attempts >= maxTries) {
    this._warn(`Pagamento ${id} não teve status reconhecido após ${maxTries} tentativas.`);
    await Cart.findOneAndUpdate(
      { channelId: this.channel.id },
      { status: 'Falha_na_verificacao', updatedAt: Date.now() },
      { upsert: true }
    );
  }
}
