```js
/**
 * CartClass — Gerenciador de carrinhos de compras (Discord × Pagamentos).
 *
 * Responsabilidades:
 *  • Criar/reutilizar carrinhos (thread privada + registro no banco)
 *  • Seleção de plano e atualização de quantidade
 *  • Geração de pagamento (Pix/TED) via PaymentProcessor
 *  • Monitoramento automático do status do pagamento
 *  • Tratamento de aprovação, cancelamento e inatividade
 *  • Aplicação de cargo pós-aprovação e instruções de resgate do bot
 *
 * Exemplo de uso:
 *   const CartClass = require('./structures/CartClass');
 *   const cart = new CartClass(client, interaction, 'sku-xyz', productData);
 *   await cart.run(interaction);
 *
 * Variáveis de ambiente recomendadas (.env):
 *   LOG_CHANNEL_ID=1264758034979360860
 *   CARGO_CLIENT_ID=995154994183548953
 *   INACTIVITY_DELAY_SEC=300
 *   POLL_PAYMENT_INTERVAL_MS=30000
 *   POLL_PAYMENT_MAX_TRIES=20
 */

const { EmbedBuilder, ActionRowBuilder, ButtonBuilder, ButtonStyle, ChannelType, ComponentType } = require('discord.js');
const PaymentProcessor = require('../structures/PaymentProcessor');
const crypto = require('crypto');

const CFG = {
  LOG_CHANNEL_ID:           process.env.LOG_CHANNEL_ID           || '1264758034979360860',
  CARGO_CLIENT_ID:          process.env.CARGO_CLIENT_ID         || '995154994183548953',
  INACTIVITY_DELAY_SEC:     parseInt(process.env.INACTIVITY_DELAY_SEC || '300', 10),
  POLL_INTERVAL_MS:         parseInt(process.env.POLL_INTERVAL_MS || '30000', 10),
  POLL_MAX_TRIES:           parseInt(process.env.POLL_MAX_TRIES || '20', 10),
  COLLECTOR_TIMEOUT_MS:     600000, // 10 minutos sem nenhum clique = carrinho encerrado
};

const CART_STATUSES = { AGUARDANDO: 'Aguardando...', PROCESSANDO: 'Processando', PAGO: 'Pago', CANCELADO: 'Cancelado' };
const PLAN_DAYS_MAP = { mensal: 30, quizena: 15, semanal: 7 };

// ── Utilitários ────────────────────────────────────────────────────────

function formatBRL(val) {
  const n = Number(val);
  if (!Number.isFinite(n)) return 'R$ 0,00';
  const int = Math.floor(n);
  const frac = (n - int).toFixed(2).replace(/^0+/, '');
  const pad = String(int).padStart(2, '0').replace(/(\d{2})(\d)/g, '$1.$2');
  return `${pad}${frac ? `,${frac}` : ''}`;
}

function _pad(s, len) { return String(s).padStart(len, '0'); }

function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

function _identity(obj) { return JSON.parse(JSON.stringify(obj)); }

/**
 * Envia mensagem por canal garantindo segurança (ignora canais saídos).
 */
async function _safeSend(channel, data) {
  if (!channel) return;
  try { return channel.send(data); } catch (_e) { /* canal abandonado */ }
}

/**
 * Envia uma edição de mensagem existente no canal do carrinho.
 * Se falhar, envia uma nova mensagem como fallback.
 */
async function _editOrCreateMessage(channel, overrides) {
  if (!channel) return;
  try {
    return channel.edit({
      content:   overrides.content   ?? undefined,
      embeds:    overrides.embeds   ?? [],
