// 6. Cancelamento de pagamentos pendentes quando o usuário cancela ou o bot Timeout
// 7. Limpeza inteligente das mensagens do canal (preserva aviso + instruções)
// 8. Uso correto de channel.edit() para atualizar o card do carrinho (sem depender de interaction.update())
// 9. Proteção contra múltiplos agendamentos e vazamento de memória nos timers (wrapCallback)
// 10. Resolução segura de canais/membros (tolera canal saído do cache)
// 11. Configuração centralizada via variáveis de ambiente
// 12. Fluxo de resgate do bot (redeem) com pattern consistente para o backend
//
// Requisite: Node ≥ 18, driver Mongoose moderno (v7+), discord.js ≥ 14.x
// ============================================================================

const { EmbedBuilder, ActionRowBuilder, ButtonBuilder, ButtonStyle, ChannelType, ComponentType } = require('discord.js');
const PaymentProcessor = require('../structures/PaymentProcessor');
const crypto = require('crypto');

const CFG = {
  LOG_CHANNEL_ID:            process.env.LOG_CHANNEL_ID            || '1264758034979360860',
  CARGO_CLIENT_ID:           process.env.CARGO_CLIENT_ID           || '995154994183548953',
  INACTIVITY_DELAY_SEC:      parseInt(process.env.INACTIVITY_DELAY_SEC || '300', 10), // 300s (5 min)
  POLL_INTERVAL_MS:          parseInt(process.env.POLL_INTERVAL_MS || '30000', 10),    // 30s
  POLL_MAX_TRIES:            parseInt(process.env.POLL_MAX_TRIES || '20', 10),          // máx. checagens
  COLLECTOR_TIMEOUT_MS:      600000, // 10 min sem cliques ⇒ carrinho encerrado
};

const STATUS_CART = { AGUARDANDO: 'Aguardando...', PROCESSANDO: 'Processando', PAGO: 'Pago', CANCELADO: 'Cancelado' };
const PLANO_DIAS  = { mensal: 30, quizena: 15, semanal: 7 };

// ------------------------------------------------------------------
// Utilitários
// ------------------------------------------------------------------
function formatBRL(valor) {
  const n = Number(valor);
  if (!Number.isFinite(n)) return 'R$ 0,00';
  const inteiro = Math.floor(n);
  const fracao  = (n - inteiro).toFixed(2).replace(/^0+/, '');
  const pad     = String(inteiro).padStart(2, '0').replace(/(\d{2})(\d)/g, '$1.$2');
  return `${pad}${fracao ? `,${fracao}` : ''}`;
}

function sleep(ms) { return new Promise(res => setTimeout(res, ms)); }

function _resolvCanal(bot, id) {
  try { const c = bot.channels.cache.get(id); return c || null; } catch (_) { return null; }
}

// ------------------------------------------------------------------
// Class principal
// ------------------------------------------------------------------
class CartClass {

  /**
   * @param {Discord.Client} client
   * @param {Discord.Interaction|null} interaction   - interação inicial do comando
   * @param {string} productId                       - SKU/id do produto
   * @param {Object} productData                     - { nome, preco: { mensal:{preco,onoff}, ... }, ... }
   * @param {string|[Discord.GuildMember]} userId    - fallback opcional do usuário (quando não houver interaction)
   */
  constructor(client, interaction, productId, productData, userId = null) {
    if (!productId) throw new Error('❌ productId obrigatório.');
    if (!productData || typeof productData !== 'object') throw new Error('❌ productData obrigatório.');
    if (!interaction && !userId) throw new Error('❌ interação ou userId obrigatórios.');

    this.client              = client;
    this.interaction         = interaction;
    this.threadInteraction   = null;
    this.targetProductId     = productId;
    this.productData         = productData;

    // ---- resolução do usuário ----
    let userObj;
    if (interaction?.user) userObj = interaction.user;
    else if (userId && client.users.cache.has(userId)) userObj = client.users.cache.get(userId);
    if (!userObj) throw new Error('❌ Usuário não identificado.');
    this.user                = userObj;
    this.user_id             = this.user.id;
    this.member              = null; // membro guild (para cargos) — salvo na primeira interação

    // ---- identificação do carrinho ----
    this.cartId              = crypto.randomBytes(16).toString('hex');
    this.channel             = null;
    this.messageId           = null;
    this.quantity            = 1;
    this.selectedPlan        = null;
    this.days                = null;
    this._deleted            = false;
    this.inactivityTimer     = null;
    this.inactivityDelay     = CFG.INACTIVITY_DELAY_SEC * 1000;
  }

  // ====== Helpers internos ================================

  _resolveCanal() {
    if (this.channel) {
      const c = this.client.channels.cache.get(this.channel.id);
      if (c) return c;
    }
    if (this.interaction?.guild?.channels?.cache?.has?.(this.channel?.id)) {
      return this.interaction.guild.channels.cache.get(this.channel.id);
    }
    return null;
  }

  _resolvCanalLogs() {
    try { return _resolvCanal(this.client, CFG.LOG_CHANNEL_ID); } catch (_) { return null; }
  }

  _garantirPlano(selecionado) {
    const p = this.productData?.preco;
    if (!p) throw new Error('❌ Preços do produto não configurados.');
    if (!p[selecionado]) throw new Error(`❌ Plano "${selecionado}" não está disponível.`);
  }

  _capitalize(str) {
    if (!str) return '';
    return str.split(' ').map(w => {
      if (w.length === 1) return w.toUpperCase();
      return w.charAt(0).toUpperCase() + w.slice(1).toLowerCase();
    }).join(' ');
  }

  _clearInatividade() {
    if (this.inactivityTimer) {
      clearInterval(this.inactivityTimer);
      this.inactivityTimer = null;
    }
  }

  static _envolverCallback(cb) {
    if (!cb) return () => {};
    return (...args) => cb.call(this, ...args);
  }

  async _resolverMembro() {
    const m = this.member
      ?? (this.threadInteraction
          ? this.threadInteraction.guild.members.cache.get(this.user.id)
          : null);
    return m ?? null;
  }

  // ====== Inatividade ==============================

  /**
   * Marca um timer de inatividade (substitui chamadas anteriores para evitar duplicidade).
   */
  _agendarInatividade(cb) {
    this._clearInatividade();
    this.inactivityTimer = setTimeout(CartClass._envolverCallback(() => cb()), this.inactivityDelay);
  }

  async handleInatividade() {
    try {
      if (this._deleted) return;
      this._deleted = true;

      const ch = await this._resolverCanal();
      if (!ch) {
        this._info('Inatividade: canal inexistente — pulando limpeza.');
        return;
      }

      // ── avisa o usuário ──
      const aviso = new EmbedBuilder()
        .setTitle('⏱️ Seu carrinho foi encerrado')
        .setColor('#FF4444')
        .setDescription([
          `Olá, **${this.user.username}**,`,
          '',
          'Sua sessão no carrinho foi interrompida por inatividade.\n',
          'Você pode iniciar uma nova compra a qualquer momento — é rapidinho! 😊',
        ]);
      await this._envioCanal(ch, aviso);

      // ── log ──
      const log = new EmbedBuilder()
        .setTitle('🧾 [LOG] Carrinho fechado por inatividade')
        .setAuthor({ name: this.client.user.username, iconURL: this.client.user.displayAvatarURL({ dynamic: true }) })
        .setFooter({ text: this.interaction?.guild?.name ?? '—', iconURL: this.interaction?.guild?.iconURL?.({ dynamic: true }) ?? undefined })
        .addFields(
          { name: '👥 Usuário',   value: `${this.user.username} #${this.user.id}` },
          { name: '🛒 Produto',   value: this.productData?.productName ?? '—' },
          { name: '🗂️ Carrinho',  value: `\`${this.cartId}\`` },
          { name: '🕒 Data/Hora', value: new Date().toLocaleString('pt-BR') },
          { name: '🔧 Motivo',     value: 'Inatividade' },
        );
      await this.sendLog(log, { titulo: 'Inatividade' });

      // ── limpa canal + registro ──
      if (this.channel) {
        try {
          const ids = await ch.messages.ids({ limit: 100 });
          if (ids.length > 2) await ch.bulkDelete(ids.slice(2, Math.min(ids.length, 52)));
          await ch.delete().catch(() => {});
        } catch (e) {
          this._warn('Falha ao limpar canal durante inatividade:', e);
        }
        try { await Cart.deleteOne({ channelId: this.channel.id }).catch(() => {}); } catch (_) {}
      }
    } catch (e) {
      this._erro('handleInatividade:', e);
    }
  }

  // ====== Carrinho / Planos =========================

  /**
   * Cria ou reaproveita um carrinho e exibe a UI de planos.
   */
  async criarCarrinho() {
    try {
      const existente = await Cart.findOne({ userId: this.user.id, status: { $ne: null } });
      if (existeite && existente.status === STATUS_CART.AGUARDANDO) {
        // Reaproveita carrinho existente
        this._restaurarExistente(existente);
        await this._exibirUI();
        this._agendarInatividade(() => this.handleInatividade(), CFG.INACTIVITY_DELAY_SEC);
        return;
      }

      // Resposta inicial ao comando
      if (this.interaction) {
        await this.interaction.reply({ content: 'Montando seu carrinho… aguarde um instante.', ephemeral: true }).catch(() => {});
      }

      // Thread privada
      const thread = await this._threadPrivado();
      this.channel = thread;

      // Registro no banco
      await Cart.updateOne(
        { userId: this.user.id, productId: this.targetProductId },
        {
          userId:        this.user.id,
          quantity:      1,
          cartId:        this.cartId,
          productId:     this.targetProductId,
          status:        STATUS_CART.AGUARDANDO,
          channelId:     this.channel.id,
        },
        { upsert: true },
      );

      // Membro da guild (para cargo posterior)
      if (this.interaction?.member) this.member = this.interaction.member;

      // Mensagem de boas-vindas com link do canal
      await this._envioCanal(thread, this._msgSucesso(thread.url));

      // UI de seleção de planos
      await this._exibirUI();
    } catch (e) {
      this._erro('criarCarrinho:', e);
    }
  }

  _restaurarExistente(doc) {
    this.cartId       = doc.id;
    this.quantity     = doc.quantity ?? 1;
    this.selectedPlan = doc.selectedPlan;
    if (this.selectedPlan) this.days = PLANO_DIAS[this.selectedPlan] ?? 30;
    else this.days = 30;
  }

  /**
   * Tenta recuperar o canal antigo reutilizado (caso a thread original tenha sido removida).
   */
  _recuperarCanalAntigo(id) {
    this.channel = _resolvCanal(this.client, id);
    return !!this.channel;
  }

  /**
   * Monta e exibe a mensagem/componentes do carrinho (planos, quantidade, ações).
   */
  async _exibirUI() {
    try {
      const ui = this._montarUI();
      await this._editarOuEnviarCanal(this.channel, ui).catch(e => this._warn('Falha ao exibir UI do carrinho:', e));
    } catch (e) {
      this._erro('_exibirUI:', e);
    }
  }

  _montarUI() {
    this._garantirPlano(this.selectedPlan);

    const dias      = this.days ?? (PLANO_DIAS[this.selectedPlan] ?? 30);
    const precoUnit = Number(this.productData.preco[this.selectedPlan]?.preco ?? 0);
    const total     = formatBRL(precoUnit * this.quantity);
    const rotulo    = this._capitalize(this.selectedPlan);

    const campos = [];
    if (precoUnit > 0) campos.push({ name: '💰 Total', value: total, inline: true });

    const embed = new EmbedBuilder()
      .setTitle('🛒 Carrinho de Compras')
      .setDescription([
        `Olá, **${this.user.username}**! 👋`,
        '',
        `Você vai adquirir **${this.productData.productName}`,
        '— um sistema exclusivo da **Nyox Applications** com qualidade premium.',
        '',
        `- 📦 **Produto:** \`${this.productData.productName}\``,
        `- ✨ **Plano:** ${rotulo} (${dias} dias)` ,
        `- 💸 **Total:** ${total}`,
      ])
      .setColor('#060A18')
      .addFields(campos);

    const linha = new ActionRowBuilder().addComponents(
      new ButtonBuilder() .setEmoji('+') .setLabel('➕1') .setStyle(ButtonStyle.Secondary).setCustomId('cartAdd'),
      new ButtonBuilder() .setEmoji('-') .setLabel('➖') .setStyle(ButtonStyle.Default).setCustomId('cartRemove'),
      new ButtonBuilder() .setLabel('✅ Finalizar Compra').setEmoji('💳').setStyle(ButtonStyle.Success).setCustomId('finalizePurchase'),
      new ButtonBuilder() .setLabel('❌ Cancelar').setStyle(ButtonStyle.Danger).setCustomId('cancelOrder'),
    );

    return { embeds: [embed], components: [linha] };
  }

  /**
   * Trata a seleção de plano (adivinhado pelo customId ou forçado).
   */
  async tratarSelecaoPlano(int, forcarNenhum = null) {
    try {
      const codigo = forcarNenhum || (int?.customId ?? null);
      if (!codigo) return; // sem plano informado, ignora

      let planoKey, dias;
      switch (codigo) {
        case '7DiasCart':     planoKey = 'semanal';     dias = 7;  break;
        case '15DiasCart':   planoKey = 'quizena';     dias = 15; break;
        case '30DiasCart':   planoKey = 'mensal';      dias = 30; break;
        default:
          return; // plano desconhecido
      }

      this._garantirPlano(planoKey);
      this.selectedPlan = planoKey;
      this.days = dias;

      // Atualiza carrinho
      await Cart.updateOne(
        { channelId: this.channel.id },
        { quantity: this.quantity, selectedPlan: planoKey },
        { upsert: true },
      );

      await this._exibirUI();
      await this.sendLog(new EmbedBuilder()
        .setTitle('🧾 Log — Novo plano escolhido')
        .addFields({ name: '👥 Usuário', value: this.user.username, inline: false },
                   { name: '🛒 Plano', value: `${planoKey} (${dias} dias)`, inline: false },
                   { name: '🕐 Agora', value: new Date().toLocaleString('pt-BR'), inline: false }),
        { titulo: 'Seleção de plano' });

      this._agendarInatividade(() => this.handleInatividade(), CFG.INACTIVITY_DELAY_SEC);
    } catch (e) {
      this._erro('tratarSelecaoPlano:', e);
    }
  }

  /**
   * Adiciona/remove item do carrinho.
   */
  async alterarQuantidade(int, acao) {
    try {
      const ch = await this._resolverCanal();
      if (!ch) return;

      if (acao === 'add') {
        if (this.quantity < 50) this.quantity += 1;
      } else { // remove
        if (this.quantity > 1) {
          this.quantity -= 1;
          // aviso efêmero pro usuário
          await int.reply?.({ embeds: [new EmbedBuilder().setDescription('➖ Item removido do carrinho. 🛒', { ephemeral: true })], components: [] }).catch(()=>{});
        } else {
          await int.reply?.({ embeds: [new EmbedBuilder().setDescription('❌ Não é possível remover todos os itens do carrinho.', { ephemeral: true })], components: [] }).catch(()=>{});
          return;
        }
      }

      await Cart.updateOne({ channelId: this.channel.id }, { quantity: this.quantity }, { upsert: true });
      await this._exibirUI();
      this._agendarInatividade(() => this.handleInatividade(), CFG.INACTIVITY_DELAY_SEC);
    } catch (e) {
      this._erro('alterarQuantidade:', e);
    }
  }

  /**
   * Finaliza a compra e gera o pagamento.
   */
  async finalizarCompra(int) {
    let jaDeferiu = false;
    try {
      jaDeferiu = true;
      const ch = await this._resolverCanal();
      if (!ch || this._deleted) throw new Error('Carrinho inválido ou já encerrado.');

      const cart = await Cart.findOne({ channelId: this.channel.id });
      if (!cart) throw new Error('Carrinho não localizado.');
      if (cart.status !== STATUS_CART.AGUARDANDO) throw new Error(`Carrinho em estado inesperado: ${cart.status}`);
      if (cart.paymentId) throw new Error('Há um pagamento em andamento neste carrinho — aguarde.');

      const p   = this.productData.preco;
      const precoUnit = Number(p[this.selectedPlan]?.preco ?? 0);
      if (precoUnit <= 0) throw new Error('Preço do plano selecionado não configurado.');

      const qtd   = Math.max(1, Math.min(50, this.quantity));
      const total = precoUnit * qtd;
      const cents = Math.round(total * 100);
      if (!Number.isInteger(cents) || cents <= 0) throw new Error('Cálculo de valor inválido.');

      const opcoes = {
        amount:         cents,
        description:    `Pedido — ${this.user.username} (${this.selectedPlan}/${this.days} dias)`,
        first_name:     this.user.first_name ?? 'Cliente',
        email:          this.user.email ?? 'pagamentos@nyox.tech',
        currency:       'BRL',
        otherData: {
          product_id:     this.targetProductId,
          cart_id:        this.cartId,
          plan:           this.selectedPlan,
          days:           this.days,
          quantity:       qtd,
          notification_url: 'https://nyox.tech/api/notifications', // adapte conforme sua rota de webhook/notificação
        },
      };

      // Notificação assíncrona opcional (gateway)
      const pid = await this.processarPagamento(opcoes);

      if (!pid) throw new Error('Gateway de pagamento recusou a criação do pagamento.');

      // salva registros persistentes
      const pagamento = new Payment({
        payment_id:     pid,
        transaction_amount: cents,
        description: opcoes.description,
        cliente_id:     this.user.id,
        email:          opcoes.email,
        status:         'Pendente',
      });
      await pagamento.save();

      await Cart.updateOne({ channelId: this.channel.id }, { paymentId: pid }, { upsert: true });

      // Monitoramento em background
      await this.monitorarPagamento(pid, opcoes, cents);
      this._info(`✅ Pagamento criado: ${pid}`);

    } catch (e) {
      if (!jaDeferiu) {
        try { await int.reply({ content: 'Ops! Não deu certo agora. Tente mais tarde. 🙏', ephemeral: true }).catch(() => {}); } catch (_) {}
      }
      await this._envioCanal(ch ?? null, `❌ Erro ao finalizar o pedido\n_${e.message.split('\n')[0]}_`);
      this._erro('finalizarCompra:', e);
    }
  }

  /**
   * Gera o pagamento via PaymentProcessor (converte para centavos para compatibilidade).
   */
  async processarPagamento(opts) {
    const proc = new PaymentProcessor();
    // Método esperado: retorna { id, attachment?, pixCopyPasteCode? }
    const resp = await proc.getPayment(92690421680); // ⚙️ Ajuste essa chave/token conforme sua implementação
    if (!resp) return null;
    return resp;
  }

  /**
   * Loop de monitoramento do status do pagamento até aprovação, cancelamento ou limite.
   */
  async monitorarPagamento(id, opts, cents) {
    let tentativas = 0;
    const aceitos = ['approved', 'paid', 'success']; // ⚙️ ajuste conforme seus estados válidos
    const cancelados = ['cancelled', 'refunded', 'expired', 'failed'];
    const intervalo = CFG.POLL_INTERVAL_MS;
    const maxTent = CFG.POLL_MAX_TRIES;
    let tick = 0;

    const checar = async () => {
      try {
        const status = await this.paymentProcessor?.checkPaymentStatus?.(id)?.then?.(s => s) ?? (await this.paymentProcessor?.checkPaymentStatus?.(id));
        // Fallback para compatibilidade caso check retorne Promise
        let st = status;
        if (st && typeof st.then === 'function') st = await st;
        // Se getPayment retornar algo que permita ler status... fallback sensato
        if (!st) { tentativas++; await sleep(intervalo); return; }

        if (aceitos.includes(st)) {
          clearInterval(tickInterval);
          await this.tratarAprovacao(id, opts);
          return;
        }
        if (cancelados.includes(st)) {
          clearInterval(tickInterval);
          await this.tratarCancelamento(id);
          return;
        }
        tentativas += 1;
        if (tentativas >= maxTent) {
          await Cart.updateOne({ channelId: this.channel.id }, { status: 'Falha_na_verificacao' }, { upsert: true }).catch(()=>{});
          this._info(`[${id}] Máximo de tentativas atingido — ficará pendente para verificação manual.`);
          return;
        }
        tick++;
        await sleep(intervalo);
      } catch (e) {
        this._warn(`Checagem de status do pagamento (${id}) falhou:`, e);
        await sleep(intervalo);
      }
    };

    const tickInterval = setInterval(checar, intervalo);
    // primeira checagem após pequeno atraso para não colidir com respostas imediatas
    setTimeout(() => checar(), 5000);
  }

  async tratarAprovacao(id, opts) {
    try {
      const cart = await Cart.findOne({ channelId: this.channel.id });
      if (!cart || cart.status === STATUS_CART.PAGO || cart.status === STATUS_CART.CANCELADO) {
        this._info(`[${id}] Cartão já finalizado — ignorando.`);
        return;
      }
      if (cart.paymentId === id) {
        this._info(`[${id}] Pagamento duplicado — ignorando.`);
        return;
      }

      cart.status = STATUS_CART.PAGO;
      cart.updatedAt = new Date();
      await cart.save();

      const membro = await this._resolverMembro();
      const cid = CFG.CARGO_CLIENT_ID;
      if (membro && cid) {
        try {
          await membro.roles.add({ id: cid }).catch(err => {
            if (err.code === 100052 || err.code === 500130) return; // member não encontrado / não possui roles
            this._warn(`Cargo indefinido para ${this.user.id}:`, err);
          });
        } catch (e) {
          this._warn(`Erro ao aplicar cargo de comprador (${cid}):`, e);
        }
      }

      const ch = await this._resolverCanal();
      if (!ch) {
        this._warn(`[${id}] Canal ausente — limpando registros.`);
        try { await Cart.deleteOne({ channelId: this.channel.id }).catch(()=>{}); } catch (_) {}
        return;
      }

      // Apaga mensagens extras preservando as 2 primeiras (aviso + instruções)
      try {
        const ids = await ch.messages.ids({ limit: 100 });
        if (ids.length > 2) await ch.bulkDelete(ids.slice(2, Math.min(ids.length, 52)));
      } catch (_) {}

      // ── mensagem final ──
      const finalMsg = new EmbedBuilder()
        .setTitle('✅ Pagamento Aprovado! 🎉')
        .setDescription([
          `Parabéns, **${this.user.username}**! Seu pagamento foi aprovado. ✅`,
          '',
          `🆔 **ID da compra:** \`${this.cartId}\``,
          '',
          'Para habilitarmos sua aplicação, precisamos de 3 informações:\n' +
          '1. Nome que você quer na aplicação\n' +
          '2. ID que será configurado como dono do bot\n' +
          '3. **Token do bot** ⚠️ Mantenha bem seguro — não compartilhe!',
        ]);

      const linhaResgate = new ActionRowBuilder().addComponents(
        new ButtonBuilder()
          .setEmoji('🤖')
          .setLabel('🎉 Receber Bot')
          .setStyle(ButtonStyle.Primary)
          .setCustomId(`redeemBot-${this.selectedPlan}-${dias}-REDEEM`), // ⚙️ backend recebe plan/days
        new ButtonBuilder()
          .setEmoji('📜')
          .setLabel('📘 Portal do Desenvolvedor')
          .setStyle(ButtonStyle.Link)
          .setURL('https://discord.com/developers/applications/')
          .setCustomId('portalDev'),
        new ButtonBuilder()
          .setEmoji('📖')
          .setLabel('🔗 Tutorial')
          .setStyle(ButtonStyle.Link)
          .setURL('https://docs.nyox.tech/tutorials/createapp'),
      );

      await this._envioCanal(ch, { embeds: [finalMsg], components: [linhaResgate] });
      await this.sendLog(new EmbedBuilder()
        .setTitle('🧾 [LOG] Pagamento aprovado')
        .addFields({ name: '👥 Usuário', value: this.user.username, inline: false },
                   { name: '🛒 Produto', value: this.productData.productName, inline: false },
                   { name: '💳 Payment ID', value: id, inline: false },
                   { name: '🕐 Horário', value: new Date().toLocaleString('pt-BR'), inline: false }),
        { titulo: 'Aprovação' });

    } catch (e) {
      this._erro('tratarAprovacao:', e);
    }
  }

  async tratarCancelamento(id = null, interacao = null) {
    try {
      // tenta cancelar pagamento pendente (se houver)
      const cart = await Cart.findOne({ channelId: this.channel.id });
      if (cart && cart.paymentId && cart.status !== STATUS_CART.PAGO && cart.status !== STATUS_CART.CANCELADO) {
        try {
          await this.paymentProcessor?.cancelPayment?.(cart.paymentId)?.catch(() => {});
        } catch (e) { this._warn(`Não foi possível cancelar o pagamento via gateway:`, e); }
      }

      const log = new EmbedBuilder()
        .setTitle('🧾 Sistema de Logs — Carrinho Cancelado')
        .setAuthor({ name: this.client.user.username, iconURL: this.client.user.displayAvatarURL({ dynamic: true }) })
        .setFooter({ text: this.interaction?.guild?.name ?? '—', iconURL: this.interaction?.guild?.iconURL?.({ dynamic: true }) ?? undefined })
        .addFields(
          { name: '👥 Usuário', value: `${this.user.username} #${this.user.id}`, inline: false },
          { name: '🛒 Produto', value: this.productData?.productName ?? '—', inline: false },
          { name: '🗂️ Carrinho', value: `\`${this.cartId}\``, inline: false },
          { name: '❔ Motivo', value: interacao?.customId === 'cancelPayment' ? 'Cancelamento explícito do pagamento' : 'Cancelamento do pedido', inline: false },
          { name: '🕐 Horário', value: new Date().toLocaleString('pt-BR'), inline: false },
        );
      await this.sendLog(log, { titulo: 'Cancelamento' });

      if (this.channel) {
        try {
          const ids = await this._resolverCanal()?.messages.ids({ limit: 100 }) ?? [];
          if (ids.length > 2) await this._resolverCanal()?.bulkDelete(ids.slice(2, Math.min(ids.length, 52))).catch(() => {});
          await this._resolverCanal()?.delete().catch(() => {});
        } catch (_) {}
        try { await Cart.deleteOne({ channelId: this.channel.id }).catch(() => {}); } catch (_) {}
      }
    } catch (e) {
      this._erro('tratarCancelamento:', e);
    }
  }

  // ====== Thread ===============================

  async _threadPrivado() {
    try {
      const canal = this.interaction?.channel;
      if (!canal) throw new Error('Interação sem canal disponível (use run() com interação).');
      return canal.threads.create({
        name: `🛒・${this.user.username}・#${this.user.id}`,
        topic: `Carrinho — ${this.productData.productName} (#${this.cartId})`,
        type: ChannelType.PrivateThread,
        reason: 'Criação de carrinho de compras Nyox',
        members: [this.user.id],
        permissionOverwrites: [
          { id: this.user.id, allow: ['ViewChannel'], deny: [] },
          { id: this.interaction.guild.id, allow: [], deny: ['ViewChannel', 'SendMessages'] },
        ],
      });
    } catch (e) {
      throw new Error(`Falha ao criar a thread: ${e.message}`);
    }
  }

  // ====== Pagamentos - fluxo de redeem ==========

  /**
   * Fluxo de resgate do bot após pagamento aprovado.
   * O backend deve detectar o padrão: redeemBot-{mensal|quizena|semanal}-{dias}-{qtd}-REDEEM
   * e enviar a cobrança dos dados (nome, ownerID, token).
   */
  async executarRedeem(plan, dias, qtd, int) {
    try {
      await int.deferUpdate().catch(() => {}); // evita problemas com double-edit
      const membro = await this._resolverMembro();
      if (membro) {
        try {
          await membro.roles.add({ id: CFG.CARGO_CLIENT_ID }).catch(err => {
            if (err.code === 100052) return; // usuário saiu do servidor
            this._warn('Falha ao aplicar role de resgate:', err);
          });
        } catch (e) { this._warn('Erro ao adicionar role de resgate:', e); }
      }

      await int.reply({
        content: `✅ **Resgate registrado!** 🚀\n\nSuas informações foram salvas com sucesso. Nossa equipe enviará as instruções finais no canal privado.\n\n*(Se você estiver testando, substitua o role assignment pelas suas regras de negócio)*`,
        ephemeral: true,
      }).catch(() => {});
    } catch (e) {
      this._erro('executarRedeem:', e);
    }
  }

  // ====== Coletor de botões (runner principal) ===

  /**
   * Inicia todo o ciclo de vida: cria o carrinho + captura cliques de botões.
   * Chame com a interação inicial do comando.
   */
  async run(initialInt = null) {
    try {
      let int = initialInt || this.interaction;
      if (int) {
        this.threadInteraction = int;
      }

      await this.criarCarrinho().catch(e => this._erro('run › criarCarrinho:', e));

      const ch = this._resolverCanal();
      if (!ch) {
        this._erro('run › nenhum canal disponível para o coletor.');
        return;
      }

      // whitelist dos comandos reconhecidos
      const VALIDOS = ['cartAdd', 'cartRemove', 'finalizePurchase', 'cancelOrder', 'cancelPayment',
                       'pixCopyPaste', 'qrCode'];
      // permite wildcard para IDs de resgate: regex específica
      const REG_DEDEEM = /^redeemBot-(mensal|quizena|semanal)-\d+-\d+-REDEEM$/;

      const coletor = ch.createMessageComponentCollector({
        componentType: ComponentType.Button,
        time: CFG.COLLECTOR_TIMEOUT_MS, // 10 min sem ação = tempo máximo do coletor
      });

      coletor.on('collect', async (btn) => {
        // anti-abuso
        if (btn.user.id !== this.user.id) {
          try { await btn.deferUpdate().catch(() => {}); } catch (_) {}
          return;
        }

        this._clearInatividade();
        this._agendarInatividade(() => this.handleInatividade(), CFG.INACTIVITY_DELAY_SEC);

        const customId = btn.customId.toLowerCase();

        switch (customId) {
          case 'cartAdd':
            await this.alterarQuantidade(btn, 'add'); break;

          case 'cartRemove':
            {
              const emb = new EmbedBuilder().setDescription('➖ Item removido do carrinho. 🛒').setEmoji('🛒');
              await btn.reply({ embeds: [emb], ephemeral: true }).catch(() => {});
              await this.alterarQuantidade(btn, 'remove');
              break;
            }

          case 'finalizePurchase':
            await this.finalizarCompra(btn);
            break;

          case 'cancelOrder':
            // cancela + limpa (inclusive pagamento pendente, se houver)
            await this.tratarCancelamento(null, btn);
            break;

          case 'cancelPayment':
            await this.tratarCancelamento(null, btn);
            break;

          case 'pixCopyPaste':
          case 'qrCode':
            await this._enviarDetalhesPagamento(btn);
            break;

          // ── IDs compostos de resgate ──
          if (REG_DEDEEM.test(customId)) {
            const partes = customId.split('-');
            // redeemBot-{plano}-{dias}-{qtd}-REDEEM
            if (partes.length >= 5 && partes[0] === 'redeemBot' && partes[3] === 'REDEEM') {
              await this.executarRedeem(partes[1], Number(partes[2]), Number(partes[3] || 1), btn);
            }
            break;
          }

          // qualquer outro comando → sinaliza desconhecido (ajuda testes)
          try {
            await btn.reply({ content: '⚠️ Este comando não está disponível neste momento.', ephemeral: true }).catch(() => {});
          } catch (_) {}
        }
      });

      coletor.on('end', async () => {
        this._clearInatividade();
        try {
          await this.limparPendencias();
        } catch (e) {
          this._erro('coletor.on(end) › limparPendencias:', e);
        }
      });
    } catch (e) {
      this._erro('run():', e);
    }
  }

  async _enviarDetalhesPagamento(int) {
    try {
      const cart = await Cart.findOne({ channelId: this.channel.id });
      if (!cart || !cart.paymentId) {
        await int.reply({ content: '⚠️ Pagamento ainda não foi gerado para este carrinho.', ephemeral: true }).catch(()=>{});
        return;
      }

      const proc = new PaymentProcessor();
      const detalhe = await proc.getPayment(cart.paymentId).catch(() => null);

      if (!detalhe) {
        await int.reply({ content: '⚠️ Não foi possível recuperar os detalhes do pagamento.', ephemeral: true }).catch(()=>{});
        return;
      }

      const files = detalhe.attachment ? [detalhe.attachment] : [];
      const msgCode = detalhe.pixCopyPasteCode;

      if (files.length > 0) {
        await int.reply({ files, ephemeral: true }).catch(() => {});
      } else if (msgCode) {
        await int.reply({ content: msgCode, ephemeral: true }).catch(() => {});
      } else {
        await int.reply({ content: '⚠️ Detalhes de pagamento indisponíveis no momento.', ephemeral: true }).catch(() => {});
      }
    } catch (e) {
      this._erro('_enviarDetalhesPagamento:', e);
      await int.reply({ content: '⚠️ Ocorreu um erro ao enviar os dados do pagamento.', ephemeral: true }).catch(() => {});
    }
  }

  async limparPendencias() {
    const pendentes = await Cart.find({ status: { $in: [STATUS_CART.AGUARDANDO, STATUS_CART.PROCESSANDO] } })
      .then(docs => docs.filter(d => d.paymentId && d.status !== STATUS_CART.PAGO)).catch(() => []);

    for (const c of pendentes) {
      try {
        if (c.paymentId) {
          try {
            await this.paymentProcessor?.cancelPayment?.(c.paymentId)?.catch(() => {});
          } catch (e) { this._warn(`Falha ao cancelar payment ${c.paymentId}:`, e); }
        }
        await Cart.updateOne({ channelId: c.channelId }, { status: STATUS_CART.CANCELADO, updatedAt: new Date() }, { upsert: true }).catch(()=>{});
      } catch (e) {
        this._warn(`Erro ao limpar carrinho ${c.id}:`, e);
      }
    }
  }

  // ====== Mensageria ===========================

  /**
   * Envia conteúdo (obj Embed ou string) pelo canal do carrinho, tratando falhas silenciosamente.
   */
  async _envioCanal(ch, data) {
    if (!ch) return;
    return _envioSilencioso(ch, data).catch(() => {});
  }

  async _editarOuEnviarCanal(ch, ui) {
    if (!ch) return;
    try {
      await ch.edit({
        embeds: ui.embeds,
        components: ui.components,
        // mantém o texto vazio pois embeds/componentes carregam a UI
      }).catch(e => this._warn('Falha ao editar mensagem do carrinho:', e));
    } catch (e) {
      // fallback: nova mensagem
      try {
        await ch.send(ui).catch(() => {});
      } catch (e2) {
        this._warn('Falha total ao atualizar UI do carrinho:', e2);
      }
    }
  }

  /**
   * Envia ao USUÁRIO (mensagem direta DM) ou pelo canal conforme contexto.
   */
  async _avisoUsuarioEmbeds(user, embeds) {
    try {
      // tenta DM primeiro (usuário sempre acessa own channel)
      const dm = await user.send({ embeds });
      if (!dm) {
        // fallback: publica no canal se estiver acessível
        const ch = await this._resolverCanal();
        if (ch) return ch.send({ embeds });
      }
      return dm;
    } catch (e) {
      this._warn('Falha ao enviar aviso ao usuário:', e);
    }
  }

  /** Wrapper de envio com tratamento de erro silencioso */
  static _envioSilencioso(channel, data) {
    return channel.send(data).catch(() => null);
  }

  // ====== Logs console ========================

  _info(msg, ...rest)  { console.info('[CART]', msg, ...rest); }
  _warn(msg, ...rest)  { console.warn('[CART]', msg, ...rest); }
  _erro(msg, ...rest)  { console.error('[CART]', msg, ...rest); }

  sendLog(embed, meta = {}) {
    const ch = this._resolvCanalLogs();
    if (!ch) return;
    const payload = { embeds: [embed] };
    if (meta.titulo) payload.fields = [{ name: '📌 Categoria', value: meta.titulo, inline: false }];
    return CartClass._envioSilencioso(ch, payload);
  }
}

module.exports = CartClass;
