```js
async monitorarPagamento(id, opts) {
  const aceitos = ['approved','paid','success'];
  const cancelados = ['cancelled','refunded','expired'];
  const intvl = CFG.POLL_INTERVAL_MS;
  let tentativas = 0;
  let falhasGatway = 0;
  const maxPol = CFG.POLL_MAX_TRIES;
  const maxFalhas = 8; // se gateway falhar muito, para e marca para revisão manual

  const checar = async () => {
    try {
      let raw;
      try { raw = await this.paymentProcessor.checkPaymentStatus(id); } catch (e) { falhasGatway++; throw e; }
      const status = raw instanceof Promise ? await raw : raw;
      falhasGatway = 0; // sucesso redefinido

      if (aceitos.includes(status)) { await this.tratarAprovacao(id); return; }
      if (cancelados.includes(status)) { await this.tratarCancelamento(id); return; }

      tentativas++;
      if (falhasGatway >= maxFalhas) {
        await Cart.updateOne({ channelId: this.channel.id }, { status: 'Falha_na_verificacao' }, { upsert: true }).catch(()=>{});
        this._warn('Gateway de pagamento fora do ar há várias tentativas — carrinho marcado para revisão manual.');
        return;
      }
      if (tentativas >= maxPol) {
        await Cart.updateOne({ channelId: this.channel.id }, { status: 'Falha_na_verificacao' }, { upsert: true }).catch(()=>{});
        return;
      }
      await sleep(intvl);
    } catch (e) {
      falhasGatway++;
      this._warn(`Checagem falhou (${id}):`, e);
      await sleep(intvl);
    }
  };

  const iv = setInterval(checar, intvl);
  setTimeout(checar, 5000);
  // limpa interval ao sair (handler de erro/limpar)
  // no final, em coletores/limparPendencias? remover: setInterval(iv, ...); // não dá pra acessar facilmente
}
```

